insert into ggo_private.editorial(kind,id,document) values('news','welcome','{"id":"welcome","title":"GG-O에서 함께 나누고 싶은 이야기","category":"서비스 안내","body":"한국 문화부터 우리의 일상까지, GG-O는 서로의 취향을 발견하는 공간입니다.\n\n소식에서는 운영자가 전하는 안내와 이야기를 읽고, 댓글로 여러분의 의견을 남길 수 있어요. 커뮤니티에서는 누구나 자신의 이야기를 시작할 수 있습니다.\n\n현재 서버 연결 테스트 중입니다. 회원 기능은 로그인 설정을 마친 뒤 이용할 수 있습니다.","image":"/images/friends.jpg"}'::jsonb) on conflict do nothing;
insert into ggo_private.editorial(kind,id,document) values('news','animation-board','{"id":"animation-board","title":"애니메이션 이야기도, 이제 GG-O에서","category":"게시판 안내","body":"좋아하는 작품, 기억에 남는 장면, 다음에 볼 작품까지. 커뮤니티의 애니메이션 게시판에서 이야기를 나눠 주세요.\n\n아직 보지 않은 사람을 위해 제목에는 스포일러를 피하고, 본문 앞에 스포일러 안내를 적어 주세요. 서로의 취향을 존중하는 댓글을 부탁드립니다.","image":"/images/concert.jpg"}'::jsonb) on conflict do nothing;
insert into ggo_private.editorial(kind,id,document) values('event','hanoi-meetup','{"id":"hanoi-meetup","title":"하노이에서, 같이 가자!","label":"커뮤니티 만남","image":"/images/cafe.jpg","description":"한국 문화를 좋아하는 사람들이 커피와 이야기를 나누는 만남을 구상하고 있어요.","location":"하노이 · 장소 추후 안내","status":"기획 중"}'::jsonb) on conflict do nothing;
insert into ggo_private.editorial(kind,id,document) values('event','k-music','{"id":"k-music","title":"우리 취향으로 채우는 밤.","label":"한국 음악 모임","image":"/images/concert.jpg","description":"좋아하는 노래를 나누고 새로운 취향을 발견하는 음악 모임을 준비하고 있어요.","location":"하노이 · 일정 미정","status":"기획 중"}'::jsonb) on conflict do nothing;
insert into ggo_private.magazine_articles(id,document) values('seoul-style','{"id":"seoul-style","tag":"스타일 이야기","title":"단순하게 입어도, 나답게.","excerpt":"서울의 거리에서 찾은 일상 코디의 작은 힌트.","image":"/images/street.jpg","read":"읽는 시간 4분","paragraphs":["좋은 스타일은 눈에 띄는 옷 한 벌에서만 시작하지 않습니다. 잘 맞는 티셔츠, 편안한 바지, 좋아하는 소품이면 나만의 이야기를 만들 수 있어요.","블랙과 화이트, 에크루를 기본으로 두고 키링이나 작은 가방에 색을 더해 보세요. 작은 변화만으로도 익숙한 옷이 새롭게 느껴집니다.","유행보다 중요한 건 내게 편한 비율과 소재입니다. 넉넉한 셔츠와 일자 바지, 부드러운 면과 탄탄한 캔버스를 자유롭게 조합해 보세요."]}'::jsonb) on conflict do nothing;
insert into ggo_private.magazine_articles(id,document) values('hanoi-cafe','{"id":"hanoi-cafe","tag":"도시 산책","title":"하노이에서 찾은 느긋한 한때.","excerpt":"혼자여도, 친구와 함께여도 좋은 카페에서의 시간.","image":"/images/cafe.jpg","read":"읽는 시간 3분","paragraphs":["좋아하는 음악과 커피 한 잔, 서두르지 않는 대화. 문화를 즐기는 방법은 이렇게 작고 일상적이기도 합니다.","자연광이 드는 자리를 찾아 책을 읽거나 잠깐 쉬어 보세요. 다른 사람이 사진에 들어간다면 먼저 동의를 구하는 것도 잊지 말고요.","좋아하는 공간이 있다면 익명 게시판에서 이야기를 나눠 주세요. 그곳이 특별한 이유가 누군가에게 새로운 영감이 될 수 있습니다."]}'::jsonb) on conflict do nothing;
insert into ggo_private.magazine_articles(id,document) values('glow-diary','{"id":"glow-diary","tag":"뷰티 노트","title":"나만의 속도로 빛나는 방법.","excerpt":"작은 습관으로 시작하는 일상의 자기 관리.","image":"/images/beauty-pink.jpg","read":"읽는 시간 3분","paragraphs":["오래 유지할 수 있는 습관이 좋은 습관입니다. 여러 제품을 한 번에 쓰기보다 피부 상태를 살피며 간단하게 시작해 보세요.","제품 설명을 읽고 작은 부위에 먼저 시험해 보세요. 자극이 생기면 전문가와 상담하는 것이 좋습니다. 이 글은 의료 조언을 대신하지 않습니다.","아름다움에 하나의 정답은 없습니다. GG-O는 각자의 취향과 모습을 편안하게 나누는 공간이 되고 싶습니다."]}'::jsonb) on conflict do nothing;
insert into public.polls(id,document,revision,active) values('ggo-tote','{"id":"ggo-tote","title":"매일 들 토트백, 어떤 색이 좋아요?","image":"/images/tote.svg","summary":"사진을 자세히 보고 나의 취향과 의견을 나눠 주세요.","revision":1,"active":true,"blocks":[{"id":"intro","type":"heading","text":"함께 고르는 다음 취향"},{"id":"body","type":"text","text":"색상과 디자인을 살펴보고 항목마다 가장 마음에 드는 보기 하나를 골라 주세요. 참여한 뒤에는 결과를 확인하고 익명으로 의견을 남길 수 있습니다."},{"id":"photo","type":"image","image":"/images/tote-black.svg","caption":"디자인과 색상을 비교해 보세요."}],"questions":[{"id":"color","prompt":"어떤 색상이 가장 마음에 드나요?","options":[{"id":"ecru-black","label":"에크루 / 블랙"},{"id":"black-white","label":"블랙 / 화이트"}]},{"id":"occasion","prompt":"어떤 용도로 선택하고 싶나요?","options":[{"id":"daily","label":"일상에서 사용"},{"id":"travel","label":"여행할 때 사용"},{"id":"gift","label":"선물용으로 선택"}]},{"id":"impression","prompt":"이 디자인에 대한 첫인상은 어떤가요?","options":[{"id":"love","label":"정말 마음에 들어요"},{"id":"more","label":"조금 더 보고 싶어요"},{"id":"other","label":"다른 디자인이 좋아요"}]}]}'::jsonb,1,true) on conflict do nothing;
insert into public.polls(id,document,revision,active) values('ggo-lip','{"id":"ggo-lip","title":"데일리 립 틴트, 어떤 색을 고를까요?","image":"/images/tint.svg","summary":"사진을 자세히 보고 나의 취향과 의견을 나눠 주세요.","revision":1,"active":true,"blocks":[{"id":"intro","type":"heading","text":"함께 고르는 다음 취향"},{"id":"body","type":"text","text":"색상과 디자인을 살펴보고 항목마다 가장 마음에 드는 보기 하나를 골라 주세요. 참여한 뒤에는 결과를 확인하고 익명으로 의견을 남길 수 있습니다."},{"id":"photo","type":"image","image":"/images/tint-peach.svg","caption":"디자인과 색상을 비교해 보세요."}],"questions":[{"id":"color","prompt":"어떤 색상이 가장 마음에 드나요?","options":[{"id":"rose","label":"01 서울 로즈"},{"id":"peach","label":"02 피치 무드"},{"id":"cherry","label":"03 체리 온"}]},{"id":"occasion","prompt":"어떤 용도로 선택하고 싶나요?","options":[{"id":"daily","label":"일상에서 사용"},{"id":"travel","label":"여행할 때 사용"},{"id":"gift","label":"선물용으로 선택"}]},{"id":"impression","prompt":"이 디자인에 대한 첫인상은 어떤가요?","options":[{"id":"love","label":"정말 마음에 들어요"},{"id":"more","label":"조금 더 보고 싶어요"},{"id":"other","label":"다른 디자인이 좋아요"}]}]}'::jsonb,1,true) on conflict do nothing;
insert into public.polls(id,document,revision,active) values('ggo-keyring','{"id":"ggo-keyring","title":"내 가방에 달 키링, 어떤 스타일이 좋아요?","image":"/images/keyring.svg","summary":"사진을 자세히 보고 나의 취향과 의견을 나눠 주세요.","revision":1,"active":true,"blocks":[{"id":"intro","type":"heading","text":"함께 고르는 다음 취향"},{"id":"body","type":"text","text":"색상과 디자인을 살펴보고 항목마다 가장 마음에 드는 보기 하나를 골라 주세요. 참여한 뒤에는 결과를 확인하고 익명으로 의견을 남길 수 있습니다."},{"id":"photo","type":"image","image":"/images/keyring-white.svg","caption":"디자인과 색상을 비교해 보세요."}],"questions":[{"id":"color","prompt":"어떤 색상이 가장 마음에 드나요?","options":[{"id":"neon","label":"네온 그린"},{"id":"white","label":"클라우드 화이트"},{"id":"black","label":"올 블랙"}]},{"id":"occasion","prompt":"어떤 용도로 선택하고 싶나요?","options":[{"id":"daily","label":"일상에서 사용"},{"id":"travel","label":"여행할 때 사용"},{"id":"gift","label":"선물용으로 선택"}]},{"id":"impression","prompt":"이 디자인에 대한 첫인상은 어떤가요?","options":[{"id":"love","label":"정말 마음에 들어요"},{"id":"more","label":"조금 더 보고 싶어요"},{"id":"other","label":"다른 디자인이 좋아요"}]}]}'::jsonb,1,true) on conflict do nothing;
